"use client"

import { Button } from "@ui-sdk/react/button"
import { ToolbarButton } from "@ui-sdk/react/toolbar"

import { cn } from "@/lib/cn"

import type { FloatingToolbarButtonProps } from "./floating-toolbar.types"
import { floatingToolbarButtonClasses } from "./floating-toolbar.variants"

// Rendered through ui-sdk's Button so agents can find and press it; a bare toolbar button isn't in their snapshot.
export function FloatingToolbarButton({ className, label, children, ...props }: FloatingToolbarButtonProps) {
  return (
    <ToolbarButton render={<Button />} aria-label={label} className={cn(floatingToolbarButtonClasses, className)} {...props}>
      <span aria-hidden="true" className="contents">
        {children}
      </span>
    </ToolbarButton>
  )
}

"use client"

import { use, useMemo } from "react"
import { MenuContent } from "@ui-sdk/react/menu"

import { cn } from "@/lib/cn"

import { FloatingToolbarContext, FloatingToolbarMenuContentContext } from "./floating-toolbar.constants"
import type { FloatingToolbarMenuContentProps } from "./floating-toolbar.types"
import { floatingToolbarMenuContentClasses, floatingToolbarPanelCounterClasses } from "./floating-toolbar.variants"

export function FloatingToolbarMenuContent({
  className,
  side,
  numbering = "none",
  sideOffset = 10,
  collisionPadding = 12,
  ...props
}: FloatingToolbarMenuContentProps) {
  const { placement } = use(FloatingToolbarContext)
  const resolvedSide = side ?? (placement === "top" ? "bottom" : "top")
  const context = useMemo(() => ({ side: resolvedSide, numbering, level: 1 as const }), [resolvedSide, numbering])

  return (
    <FloatingToolbarMenuContentContext value={context}>
      <MenuContent
        side={resolvedSide}
        sideOffset={sideOffset}
        collisionPadding={collisionPadding}
        data-numbering={numbering}
        className={cn(floatingToolbarMenuContentClasses, floatingToolbarPanelCounterClasses[1], className)}
        {...props}
      />
    </FloatingToolbarMenuContentContext>
  )
}

"use client"

import { use } from "react"
import { MenuItem, MenuItemIcon } from "@ui-sdk/react/menu"

import { cn } from "@/lib/cn"

import { FloatingToolbarMenuContentContext } from "./floating-toolbar.constants"
import type { FloatingToolbarMenuItemProps } from "./floating-toolbar.types"
import {
  floatingToolbarItemNumberClasses,
  floatingToolbarMenuItemClasses,
  floatingToolbarMenuItemIconClasses,
  floatingToolbarMenuItemLabelClasses,
} from "./floating-toolbar.variants"

export function FloatingToolbarMenuItem({ className, icon, children, ...props }: FloatingToolbarMenuItemProps) {
  const { numbering, level } = use(FloatingToolbarMenuContentContext)

  return (
    <MenuItem className={cn(floatingToolbarMenuItemClasses, floatingToolbarItemNumberClasses[level][numbering], className)} {...props}>
      {icon && <MenuItemIcon className={floatingToolbarMenuItemIconClasses}>{icon}</MenuItemIcon>}
      <span className={floatingToolbarMenuItemLabelClasses}>{children}</span>
    </MenuItem>
  )
}

