"use client"

import { useMemo, useState } from "react"
import { MenuSub } from "@ui-sdk/react/menu"

import { FloatingToolbarSubmenuContext } from "./floating-toolbar.constants"
import type { FloatingToolbarSubmenuProps } from "./floating-toolbar.types"

export function FloatingToolbarSubmenu({ defaultOpen = false, onOpenChange, ...props }: FloatingToolbarSubmenuProps) {
  const [open, setOpen] = useState(defaultOpen)
  const context = useMemo(() => ({ open, setOpen }), [open])

  return (
    <FloatingToolbarSubmenuContext value={context}>
      <MenuSub
        open={open}
        onOpenChange={(next, details) => {
          onOpenChange?.(next, details)
          if (!details.canceled) setOpen(next)
        }}
        {...props}
      />
    </FloatingToolbarSubmenuContext>
  )
}

import { createContext } from "react"

import type {
  FloatingToolbarContextValue,
  FloatingToolbarMenuContentContextValue,
  FloatingToolbarSubmenuState,
} from "./floating-toolbar.types"

export const FloatingToolbarContext = createContext<FloatingToolbarContextValue>({ placement: "inline" })

export const FloatingToolbarMenuContentContext = createContext<FloatingToolbarMenuContentContextValue>({
  side: "top",
  numbering: "none",
  level: 1,
})

export const FloatingToolbarSubmenuContext = createContext<FloatingToolbarSubmenuState | null>(null)

"use client"

import { useMemo, useRef } from "react"
import { Toolbar } from "@ui-sdk/react/toolbar"

import { cn } from "@/lib/cn"

import { FloatingToolbarContext } from "./floating-toolbar.constants"
import type { FloatingToolbarProps } from "./floating-toolbar.types"
import {
  floatingToolbarClasses,
  floatingToolbarSurfaceClasses,
  floatingToolbarWrapperClasses,
} from "./floating-toolbar.variants"
import { useScrollEdges } from "./use-scroll-edges"

export function FloatingToolbar({
  className,
  wrapperClassName,
  placement = "bottom",
  children,
  ...props
}: FloatingToolbarProps) {
  const scrollerRef = useRef<HTMLDivElement>(null)
  useScrollEdges(scrollerRef)
  const context = useMemo(() => ({ placement }), [placement])

  return (
    <FloatingToolbarContext value={context}>
      <div data-slot="floating-toolbar-wrapper" data-placement={placement} className={cn(floatingToolbarWrapperClasses[placement], wrapperClassName)}>
        <div data-slot="floating-toolbar-surface" className={cn(floatingToolbarSurfaceClasses, className)}>
          <Toolbar ref={scrollerRef} data-placement={placement} className={floatingToolbarClasses} {...props}>
            {children}
          </Toolbar>
        </div>
      </div>
    </FloatingToolbarContext>
  )
}

import type { ComponentProps, ReactNode } from "react"
import type { Menu, MenuContent, MenuItem, MenuSub, MenuSubContent, MenuSubTrigger } from "@ui-sdk/react/menu"
import type { Toolbar, ToolbarButton, ToolbarSeparator } from "@ui-sdk/react/toolbar"

/** Where the toolbar floats: pinned to the bottom or top of the viewport, or in the page flow. */
export type FloatingToolbarPlacement = "bottom" | "top" | "inline"

export type FloatingToolbarProps = Omit<ComponentProps<typeof Toolbar>, "className" | "orientation" | "children"> & {
  /** Classes for the visible pill (background, border, shadow) around the scrolling options. */
  className?: string
  children?: ReactNode
  /** Defaults to "bottom". */
  placement?: FloatingToolbarPlacement
  /** Classes for the positioning wrapper around the toolbar. */
  wrapperClassName?: string
}

export type FloatingToolbarButtonProps = Omit<ComponentProps<typeof ToolbarButton>, "className" | "children"> & {
  className?: string
  /** Accessible name of the icon-only button. */
  label: string
  /** The icon. Rendered with `aria-hidden`. */
  children: ReactNode
}

export type FloatingToolbarSeparatorProps = Omit<ComponentProps<typeof ToolbarSeparator>, "className"> & {
  className?: string
}

export type FloatingToolbarMenuProps = ComponentProps<typeof Menu>

export type FloatingToolbarMenuTriggerProps = FloatingToolbarButtonProps

export type FloatingToolbarMenuContentProps = Omit<ComponentProps<typeof MenuContent>, "className" | "side"> & {
  className?: string
  /** Side of the toolbar the panel opens on. Defaults to "top", or "bottom" for a toolbar placed at the top. */
  side?: FloatingToolbarSide
  /** Shows a number at the end of each item, like a part number. Defaults to "none". */
  numbering?: FloatingToolbarNumbering
}

export type FloatingToolbarMenuItemProps = Omit<ComponentProps<typeof MenuItem>, "className" | "children"> & {
  className?: string
  children?: ReactNode
  /** Decorative icon before the text. */
  icon?: ReactNode
}

/** Uncontrolled: the back item and the menu keys open and close it. Use `onOpenChange` to observe it. */
export type FloatingToolbarSubmenuProps = Omit<ComponentProps<typeof MenuSub>, "open">

export type FloatingToolbarSubmenuTriggerProps = Omit<ComponentProps<typeof MenuSubTrigger>, "className" | "children"> & {
  className?: string
  children?: ReactNode
  /** Decorative icon before the text. */
  icon?: ReactNode
}

export type FloatingToolbarSubmenuContentProps = Omit<
  ComponentProps<typeof MenuSubContent>,
  "className" | "children" | "side" | "align" | "anchor" | "sideOffset" | "alignOffset"
> & {
  className?: string
  children?: ReactNode
  /** Heading shown under the back item; also names the group of sub-items. */
  title?: string
  /** Text of the item that closes this panel and returns to the previous one. Defaults to "Back". */
  backLabel?: string
  /** Numbering for this panel's items. Defaults to the parent panel's. */
  numbering?: FloatingToolbarNumbering
}

export type FloatingToolbarSubmenuState = {
  open: boolean
  setOpen: (open: boolean) => void
}

export type FloatingToolbarSide = NonNullable<ComponentProps<typeof MenuContent>["side"]>

export type FloatingToolbarContextValue = {
  placement: FloatingToolbarPlacement
}

/**
 * How panel items are numbered. `sequential`: 01, 02, 03 in every panel.
 * `hierarchical`: a nested panel prefixes its parent item's number (03.1, 03.2).
 */
export type FloatingToolbarNumbering = "none" | "sequential" | "hierarchical"

/** 1 for a panel opened from the toolbar, 2 for a panel opened over it. */
export type FloatingToolbarPanelLevel = 1 | 2

export type FloatingToolbarMenuContentContextValue = {
  side: FloatingToolbarSide
  numbering: FloatingToolbarNumbering
  level: FloatingToolbarPanelLevel
}

import type { FloatingToolbarNumbering, FloatingToolbarPanelLevel, FloatingToolbarPlacement } from "./floating-toolbar.types"

export const floatingToolbarWrapperClasses = {
  bottom: "pointer-events-none fixed inset-x-4 bottom-[max(1rem,env(safe-area-inset-bottom))] z-40 flex justify-center",
  top: "pointer-events-none fixed inset-x-4 top-[max(1rem,env(safe-area-inset-top))] z-40 flex justify-center",
  inline: "flex w-full min-w-0 justify-center",
} satisfies Record<FloatingToolbarPlacement, string>

// Primary-colored brackets on two opposite corners, like the crop marks on a technical drawing.
const cornerMarkClasses = [
  "before:pointer-events-none before:absolute before:size-2 before:rounded-tl-sm before:border-t before:border-l before:border-primary",
  "after:pointer-events-none after:absolute after:size-2 after:rounded-br-sm after:border-r after:border-b after:border-primary",
].join(" ")

// On the toolbar the brackets sit over its border; panels scroll, so theirs stay inside it to avoid overflow.
const outerCornerClasses = "before:-top-px before:-left-px after:-right-px after:-bottom-px"
const innerCornerClasses = "before:top-0 before:left-0 after:right-0 after:bottom-0"

// The surface carries the background, so the edge fades on the scroller inside only fade the options.
export const floatingToolbarSurfaceClasses = [
  "pointer-events-auto relative flex max-w-full min-w-0 rounded-sm border border-border bg-popover text-popover-foreground shadow-elevated",
  cornerMarkClasses,
  outerCornerClasses,
].join(" ")

// The toolbar is its own horizontal scroller: on narrow screens a finger drags it sideways,
// and roving focus scrolls the focused item into view.
export const floatingToolbarClasses = [
  "flex max-w-full min-w-0 items-center gap-1 overflow-x-auto overscroll-x-contain rounded-sm p-1.5",
  "scroll-px-16 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden",
  // With the scrollbar hidden, these fades are the only cue that more items exist past an edge.
  "data-more-start:mask-l-from-[calc(100%-4rem)] data-more-end:mask-r-from-[calc(100%-4rem)]",
  "data-disabled:opacity-60",
].join(" ")

export const floatingToolbarButtonClasses = [
  "inline-flex size-10 shrink-0 items-center justify-center rounded-xs text-muted-foreground outline-none",
  "transition-[background-color,color,box-shadow] duration-150 ease-out motion-reduce:transition-none",
  "hover:bg-accent hover:text-accent-foreground active:bg-accent/70",
  "focus-visible:inset-ring focus-visible:inset-ring-ring",
  "data-open:bg-primary/10 data-open:text-primary data-open:inset-ring data-open:inset-ring-primary/50",
  "data-disabled:pointer-events-none data-disabled:opacity-50",
  "[&_svg]:size-5 [&_svg]:shrink-0 [&_svg]:stroke-[1.75]",
].join(" ")

export const floatingToolbarSeparatorClasses = "mx-1 h-6 w-px shrink-0 bg-border"

const panelClasses = [
  "z-50 flex max-h-(--available-height) min-w-52 flex-col overflow-y-auto overscroll-contain rounded-sm border border-border bg-popover p-1 text-popover-foreground shadow-elevated outline-none",
  cornerMarkClasses,
  innerCornerClasses,
].join(" ")

export const floatingToolbarMenuContentClasses = [
  panelClasses,
  "transition-[opacity,translate] duration-150 ease-out motion-reduce:transition-none",
  "data-starting-style:opacity-0 data-ending-style:opacity-0",
  "data-starting-style:data-[side=top]:translate-y-1 data-starting-style:data-[side=bottom]:-translate-y-1",
  "motion-reduce:data-starting-style:translate-y-0",
  // While a nested panel covers this one, hide its items so none show around the edges.
  "[&:has(>[data-nested][data-open])>:not([data-nested])]:invisible",
].join(" ")

// Nested panels open over their parent, so they take its width and slide in from the inline end.
export const floatingToolbarSubmenuContentClasses = [
  panelClasses,
  "w-(--anchor-width)",
  "transition-[opacity,translate] duration-150 ease-out motion-reduce:transition-none",
  "data-starting-style:translate-x-3 data-starting-style:opacity-0 data-ending-style:translate-x-3 data-ending-style:opacity-0",
  "rtl:data-starting-style:-translate-x-3 rtl:data-ending-style:-translate-x-3",
  "motion-reduce:data-starting-style:translate-x-0 motion-reduce:data-ending-style:translate-x-0",
].join(" ")

export const floatingToolbarMenuItemClasses = [
  "group/item flex min-h-9 cursor-default items-center gap-2.5 rounded-xs px-2.5 py-1.5 text-sm outline-none select-none",
  "data-highlighted:bg-accent data-highlighted:text-accent-foreground",
  "data-disabled:pointer-events-none data-disabled:opacity-50",
  "data-destructive:text-error data-destructive:data-highlighted:bg-error/10",
  "[&_svg]:size-4 [&_svg]:shrink-0 [&_svg]:stroke-[1.75]",
].join(" ")

export const floatingToolbarMenuItemIconClasses =
  "inline-flex text-muted-foreground group-data-highlighted/item:text-primary"

export const floatingToolbarMenuItemLabelClasses = "min-w-0 flex-1"

export const floatingToolbarSubmenuChevronClasses = "text-muted-foreground rtl:-scale-x-100"

// Numbers come from CSS counters, so they follow item order with no bookkeeping. Each panel resets
// its counter; a nested panel sits after its trigger in the DOM, so it can still read the parent's.
// The `/ ""` alternative text keeps the number out of the item's accessible name.
export const floatingToolbarPanelCounterClasses = {
  1: "[counter-reset:ft-item]",
  2: "[counter-reset:ft-sub]",
} satisfies Record<FloatingToolbarPanelLevel, string>

const numberClasses =
  "after:min-w-[2ch] after:text-end after:font-mono after:text-2xs after:tracking-wide after:text-muted-foreground data-highlighted:after:text-primary"

export const floatingToolbarItemNumberClasses = {
  1: {
    none: "",
    sequential: `[counter-increment:ft-item] after:content-[counter(ft-item,decimal-leading-zero)_/_""] ${numberClasses}`,
    hierarchical: `[counter-increment:ft-item] after:content-[counter(ft-item,decimal-leading-zero)_/_""] ${numberClasses}`,
  },
  2: {
    none: "",
    sequential: `[counter-increment:ft-sub] after:content-[counter(ft-sub,decimal-leading-zero)_/_""] ${numberClasses}`,
    hierarchical: `[counter-increment:ft-sub] after:content-[counter(ft-item,decimal-leading-zero)_"."_counter(ft-sub)_/_""] ${numberClasses}`,
  },
} satisfies Record<FloatingToolbarPanelLevel, Record<FloatingToolbarNumbering, string>>

export const floatingToolbarBackItemClasses = "min-h-8 font-mono text-2xs tracking-wide text-muted-foreground uppercase"

export const floatingToolbarSubmenuTitleClasses = "px-2.5 pt-2 pb-1 font-mono text-2xs tracking-wide text-primary uppercase"

export const floatingToolbarMenuSeparatorClasses = "-mx-1 my-1 h-px bg-border"

import { useEffect } from "react"
import type { RefObject } from "react"

/**
 * Marks a horizontal scroller with `data-more-start` / `data-more-end` while content
 * hides past that edge. Reads the scroll position on scroll, resize and content changes,
 * so it updates synchronously in every browser.
 */
export function useScrollEdges(scrollerRef: RefObject<HTMLElement | null>) {
  useEffect(() => {
    const root = scrollerRef.current
    if (!root) return

    const update = () => {
      // scrollLeft is negative in right-to-left scrollers, so measure its distance from 0.
      const fromStart = Math.abs(root.scrollLeft)
      const overflow = root.scrollWidth - root.clientWidth
      root.toggleAttribute("data-more-start", fromStart > 1)
      root.toggleAttribute("data-more-end", overflow - fromStart > 1)
    }

    update()
    root.addEventListener("scroll", update, { passive: true })
    const resize = typeof ResizeObserver === "undefined" ? null : new ResizeObserver(update)
    resize?.observe(root)
    const mutation = typeof MutationObserver === "undefined" ? null : new MutationObserver(update)
    mutation?.observe(root, { childList: true, subtree: true })

    return () => {
      root.removeEventListener("scroll", update)
      resize?.disconnect()
      mutation?.disconnect()
    }
  }, [scrollerRef])
}
